"""Restricted, human-only safety review workspace."""
HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>安全事件人工核查</title>
<style>
*{box-sizing:border-box;letter-spacing:0}body{margin:0;background:#f5f8fc;color:#20364e;font:15px/1.7 "Microsoft YaHei UI",sans-serif}header{padding:20px 5%;background:white;border-bottom:1px solid #dce5ef;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}a{color:#225eca;text-decoration:none}nav{display:flex;gap:20px}main{max-width:1200px;margin:auto;padding:28px 24px}h1{font-size:25px}h2{font-size:19px}h3{font-size:16px}p{margin:8px 0}.notice{border-left:3px solid #bd7d21;background:#fff8e9;padding:12px 16px}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:28px;margin-top:24px}aside{border-right:1px solid #dce5ef;padding-right:20px}section{min-width:0}label{display:block;margin:14px 0 6px}input,select,textarea,button{font:inherit;max-width:100%}input:not([type=checkbox]),select,textarea{width:100%;padding:9px;border:1px solid #c9d6e5;border-radius:5px;background:white}textarea{min-height:100px;resize:vertical}button{padding:8px 15px;border:1px solid #c9d6e5;border-radius:5px;cursor:pointer;background:white;color:#245dc0}button.primary{background:#245dc0;color:white}.row{display:flex;gap:12px;flex-wrap:wrap}.row>label{flex:1;min-width:110px}.entry{width:100%;margin-bottom:8px;text-align:left;overflow-wrap:anywhere}.muted{color:#61758c;font-size:13px}.block{border-top:1px solid #dce5ef;margin-top:22px;padding-top:14px}video{width:100%;max-height:400px;background:#152130;aspect-ratio:16/9}#msg{color:#9a3d24;white-space:pre-wrap}#detail p{white-space:pre-wrap;overflow-wrap:anywhere}[hidden]{display:none!important}:focus-visible{outline:3px solid #86b0f1;outline-offset:2px}button:disabled{opacity:.5;cursor:wait}@media(max-width:700px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid #dce5ef;padding:0 0 18px}main{padding:18px}h1{font-size:22px}}
</style></head><body><header><strong>课堂安全 · 人工核查</strong><nav><a href="/demo2/upload">课堂视频</a><a href="/demo2/evaluation">课堂评价</a></nav></header><main>
<h1>安全事件核查</h1><p class="notice">若现场存在即时危险，请按学校安全流程及时处理，不要等待平台核查。本页不自动认定伤害，不自动扣分。</p>
<p id="msg" role="alert"></p><div class="layout"><aside><button id="new" class="primary">提交核查</button><h2>我的相关事件</h2><div id="list"></div></aside><section>
<form id="create"><h2>记录客观观察</h2><label>课堂视频<select id="task" required></select></label><video id="source" controls preload="metadata"></video><div class="row"><label>开始秒数<input id="start" type="number" min="0" step="0.1" required></label><label>结束秒数<input id="end" type="number" min="0" step="0.1" required></label></div><div class="row"><button type="button" id="markStart">当前位置设为开始</button><button type="button" id="markEnd">当前位置设为结束</button></div><label>观察到的具体情况<textarea id="observation" maxlength="200" required placeholder="记录可见动作和前后情境，避免未经核实的定性或学生诊断信息。"></textarea></label><label>现场已采取的措施<textarea id="action" maxlength="200" placeholder="尚未采取措施可留空"></textarea></label><p class="muted">保留原视频引用，不复制录像、不延长原视频保存期。核查说明最长保存60天，不晚于原视频到期；到期后访问时清理，不进入训练集。</p><button class="primary">保存为待核查</button></form>
<section id="detail" hidden><h2 id="title"></h2><p id="meta" class="muted"></p><video id="reviewVideo" controls preload="metadata"></video><button id="clip">回看事件前后</button><p id="mediaMsg" class="muted"></p><h3>客观观察</h3><p id="facts"></p><h3>现场措施</h3><p id="measures"></p>
<form id="assign" class="block"><h3>指定 / 撤销核查人</h3><label>同校账号<select id="reviewer"></select></label><p class="muted">提交者不能核查自己的事件。请核对账号身份，并取得学校授权。指定后，该账号可查看本事件说明及关联的完整原视频（含音频），不会获得其他档案权限。选择“暂不指定”可撤销访问。</p><label>授权依据或变更原因<input id="assignNote" maxlength="2000" required></label><label><input id="authorization" type="checkbox" required> 已确认学校授权及核查人身份</label><button>保存授权</button></form>
<form id="review" class="block"><h3>核查结论</h3><label>结果<select id="status"><option value="supplement">补充材料中</option><option value="verified">已核实</option><option value="ruled_out">已排除</option><option value="unclear">无法判断</option></select></label><label>核查依据、结论及后续处理<textarea id="reviewNote" maxlength="2000" required></textarea></label><label><input id="conflict" type="checkbox" required> 我是指定核查人，无利益冲突，已核对前后情境；结论是人工记录而非系统裁决</label><button class="primary">记录核查结论</button></form>
<form id="supplement" class="block"><h3>补充材料 / 申请重新核查</h3><textarea id="supplementNote" maxlength="2000" required></textarea><p class="muted">补充后状态转为“补充材料中”，旧结论保留在记录中。</p><button>提交补充</button></form><div class="block"><h3>处理记录</h3><div id="history"></div></div></section>
</section></div></main><script>
const $=id=>document.getElementById(id);let work,active,busy=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(route,data){const r=await fetch('/api/v1/demo2/safety'+route,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error?.message||j.message||'操作失败，请刷新后核对');return j;}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);$('msg').textContent='';try{await fn();}catch(e){$('msg').textContent=e.message;}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function load(id){work=(await api('')).workspace;$('list').innerHTML=work.events.map(e=>`<button class="entry" data-id="${esc(e.id)}">${esc(work.states[e.status])} · ${e.start_sec}-${e.end_sec}秒<br><small>${e.reviewer?'已指定核查人':'待指定负责人'}</small></button>`).join('')||'<p class="muted">暂无相关事件</p>';$('task').innerHTML='<option value="">选择视频</option>'+work.tasks.map(t=>`<option value="${esc(t.task_id)}">${esc(t.course_name)} · ${esc(t.task_id.slice(0,8))}</option>`).join('');if(id)openEvent(id);}
function openEvent(id){active=work.events.find(e=>e.id===id);if(!active)return;$('source').pause();$('source').removeAttribute('src');$('create').hidden=true;$('detail').hidden=false;$('title').textContent=work.states[active.status];$('meta').textContent=`事件 ${active.id.slice(0,8)} · 版本 ${active.version} · 到期 ${active.expires_at.slice(0,10)}`;$('facts').textContent=active.observation;$('measures').textContent=active.action||'未填写';$('reviewVideo').src='/api/v1/demo2/safety/media?id='+encodeURIComponent(id);$('mediaMsg').textContent='';$('assign').hidden=active.owner!==work.account_id;$('review').hidden=active.reviewer!==work.account_id;$('reviewer').innerHTML='<option value="">暂不指定 / 撤销授权</option>'+work.reviewers.map(r=>`<option value="${esc(r.id)}">${esc(r.label)}</option>`).join('');$('reviewer').value=active.reviewer;for(const f of ['assignNote','reviewNote','supplementNote'])$(f).value='';$('authorization').checked=false;$('conflict').checked=false;$('history').innerHTML=active.history.map(h=>`<p><strong>${esc(work.states[h.status])}</strong> · ${esc(h.at)}<br>${esc(h.actor===work.account_id?'当前账号':h.actor===active.owner?'提交者':'核查账号')}：${esc(h.note)}</p>`).join('');}
async function update(command,note,confirmed=false){await api('/update',{id:active.id,version:active.version,command,reviewer:$('reviewer').value,status:$('status').value,note,confirmed});await load(active.id);}
$('list').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openEvent(b.dataset.id);};$('new').onclick=()=>{$('reviewVideo').pause();$('reviewVideo').removeAttribute('src');active=null;$('detail').hidden=true;$('create').hidden=false;};$('task').onchange=()=>{$('source').src='/api/v1/demo2/upload/media?id='+encodeURIComponent($('task').value);};for(const [b,f]of [['markStart','start'],['markEnd','end']])$(b).onclick=()=>{$(f).value=$('source').currentTime.toFixed(1);};$('clip').onclick=()=>{$('reviewVideo').currentTime=Math.max(0,active.start_sec-10);$('reviewVideo').play().catch(()=>{$('mediaMsg').textContent='请点击播放器播放';});};$('reviewVideo').ontimeupdate=()=>{if(active&&$('reviewVideo').currentTime>=active.end_sec+10)$('reviewVideo').pause();};$('reviewVideo').onerror=()=>{$('mediaMsg').textContent='视频已到期、权限变化或暂不可用，请勿仅凭摘要下结论。';};
$('create').onsubmit=e=>{e.preventDefault();run(async()=>{const j=await api('/create',{task_id:$('task').value,start_sec:Number($('start').value),end_sec:Number($('end').value),observation:$('observation').value,action:$('action').value});$('create').reset();await load(j.record.id);});};$('assign').onsubmit=e=>{e.preventDefault();run(()=>update('assign',$('assignNote').value,$('authorization').checked));};$('review').onsubmit=e=>{e.preventDefault();run(()=>update('resolve',$('reviewNote').value,$('conflict').checked));};$('supplement').onsubmit=e=>{e.preventDefault();run(()=>update('supplement',$('supplementNote').value));};run(async()=>{await load();const t=new URLSearchParams(location.search).get('task_id');if(t&&work.tasks.some(x=>x.task_id===t)){$('task').value=t;$('task').dispatchEvent(new Event('change'));}});
</script></body></html>'''
